def solve(grid):
    R = len(grid)
    count = 0
    seen = set()
    def is_land(v):
        return v == 1 or v == '1'
    for r in range(R):
        row = grid[r]
        for c in range(len(row)):
            if not is_land(row[c]) or (r, c) in seen:
                continue
            count += 1
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                i, j = stack.pop()
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ni, nj = i + di, j + dj
                    if ni < 0 or ni >= R or (ni, nj) in seen:
                        continue
                    nrow = grid[ni]
                    if not (0 <= nj < len(nrow)):
                        continue
                    if is_land(nrow[nj]):
                        seen.add((ni, nj))
                        stack.append((ni, nj))
    return count

