def solve(words):
    groups = {}
    for w in words:
        key = ''.join(sorted(w))
        groups.setdefault(key, []).append(w)
    out = []
    for g in groups.values():
        g.sort()
        out.append(g)
    out.sort(key=lambda g: g[0])
    return out

